def check_rows(rows):
    errors = []
    for n, row in enumerate(rows, 2):
        if not row.get('id', '').strip():
            errors.append((n, 'id'))
        try:
            amount = int(row.get('amount', ''))
        except ValueError:
            amount = -1
        if amount < 0:
            errors.append((n, 'amount'))
    return errors

def reconcile(rows):
    seen, result = set(), {}
    for oid, zone, amount in rows:
        if oid in seen:
            continue
        seen.add(oid)
        count, total = result.get(zone, (0,0))
        result[zone] = (count+1, total+amount)
    return result

def features_asof(events, cutoff):
    latest = {}
    for key, at, value in events:
        if at <= cutoff and (key not in latest or latest[key][0] <= at):
            latest[key] = (at, value)
    return {key: item[1] for key, item in latest.items()}

def train_step(state, batch, lr):
    dw = db = 0.0
    for x,y in batch:
        error = state['w']*x + state['b'] - y
        dw += 2*error*x
        db += 2*error
    return {'w': state['w']-lr*dw/len(batch), 'b':state['b']-lr*db/len(batch), 'step':state['step']+1}

def backtest(series):
    if len(series) <= 7:
        return None, None
    times = range(7, len(series))
    return tuple(sum(abs(series[t] - series[t-lag]) for t in times) / len(times) for lag in (7,1))

def light_errors(rows, train_objects):
    known = set(train_objects)
    counts = {}
    for obj, light, target, pred in rows:
        if obj in known:
            continue
        bad, n = counts.get(light, (0,0))
        counts[light] = (bad + (target != pred), n+1)
    return {light: bad/n for light,(bad,n) in counts.items()}

def grounded_context(hits, allowed, threshold):
    result = []
    for key, version, score in hits:
        if key in allowed and allowed[key] == version and score >= threshold and key not in result:
            result.append(key)
            if len(result) == 2:
                break
    return result

def last_good_release(releases, schema):
    for release in reversed(releases):
        if release['schema'] == schema and release['smoke_ok'] and release['healthy']:
            return release['id']
    return None

def duplicate_keys(right_ids):
    from collections import Counter
    return sorted(k for k, n in Counter(right_ids).items() if n > 1)

def positive_recall(truth, pred):
    positives = sum(t == 1 for t in truth)
    return sum(t == 1 and p == 1 for t,p in zip(truth,pred)) / positives if positives else 0.0

def threshold_cost(truth, scores, threshold):
    cost = 0
    for actual, score in zip(truth, scores):
        positive = score >= threshold
        cost += 2 if positive and not actual else 7 if actual and not positive else 0
    return cost
